/**
 * 负责游戏装配前的生产有限板子拒绝分派。输入为规范化的 ReadonlyBoardConfig，
 * 输出为既有顺序中的首个违规码或 null；不创建角色、状态或效果。
 * 猎魔人分支先经过其 Node 自有数据快照入口，再执行有限纯数据判定。
 * 单个裁决不授予运行能力；归档验证不导入本生产分派或其政策。
 */
import {
  isAnimalDreamPreset,
  isFragrantPairSeerPreset,
  isNobleSecretBodyPreset,
  isTricksterPreset,
  isOrderPrincePreset,
  isScholarMentorPreset,
  isMistRavenPreset,
  isRadiantEclipsePreset,
  isTimeConsortPreset,
  isWolfSorcererPreset,
  isMagicianPreset,
  isRedMoonPreset,
  isNightmarePreset,
  isEvilKnightPreset,
  isPureWhitePreset,
  isGhostBridePreset,
} from "./support";
import { Role, WinCondition } from "@ai-werewolf-arena/game-contract";
import type { ReadonlyBoardConfig } from "@ai-werewolf-arena/game-contract";
import { isDemonHunterPreset } from "./node-board-support";

/** 配置检查与直接 bootstrap 调用方共用有限支持裁决；首个违规命中即返回，后续分支不再读取。 */
export function boardPresetViolation(config: ReadonlyBoardConfig) {
  if (
    (config.animalDream ||
      config.bear?.signalPolicy === "netease_dawn_live_v1" ||
      config.whiteCat ||
      config.pufferfish ||
      config.roleSetups.some(
        (row) => [Role.WhiteCat, Role.FoxCub, Role.Pufferfish].includes(row.role) && row.count > 0,
      )) &&
    !isAnimalDreamPreset(config)
  )
    return "animal_dream_preset_invalid";
  if (config.bear && !config.roleSetups.some((row) => row.role === Role.Bear && row.count > 0))
    return "bear_role_required";
  if (
    (config.fragrantPairSeer ||
      config.roleSetups.some(
        (row) =>
          (row.role === Role.FragrantPhantom || row.role === Role.AwakenedSeer) && row.count > 0,
      )) &&
    !isFragrantPairSeerPreset(config)
  )
    return "fragrant_pair_seer_preset_invalid";
  if (
    (config.nobleSecretBody ||
      config.nightNoble ||
      config.awakenedIdiot ||
      config.roleSetups.some(
        (row) => [Role.NightNoble, Role.AwakenedIdiot].includes(row.role) && row.count > 0,
      )) &&
    !isNobleSecretBodyPreset(config)
  )
    return "noble_secret_body_preset_invalid";
  if (
    (config.radiantEclipse ||
      config.roleSetups.some(
        (row) => (row.role === Role.RadiantCount || row.role === Role.EclipseMaid) && row.count > 0,
      )) &&
    !isRadiantEclipsePreset(config)
  )
    return "radiant_eclipse_preset_invalid";
  if (
    (config.mistRaven ||
      config.roleSetups.some(
        (row) => (row.role === Role.Alchemist || row.role === Role.RavenClawWolf) && row.count > 0,
      )) &&
    !isMistRavenPreset(config)
  )
    return "mist_raven_preset_invalid";
  if (
    (config.trickster ||
      config.roleSetups.some((row) => row.role === Role.Trickster && row.count > 0)) &&
    !isTricksterPreset(config)
  )
    return "trickster_preset_invalid";
  if (
    (config.scholarMentor ||
      config.roleSetups.some(
        (row) => (row.role === Role.DayScholar || row.role === Role.NightMentor) && row.count > 0,
      )) &&
    !isScholarMentorPreset(config)
  )
    return "scholar_mentor_preset_invalid";
  if (
    (config.timeConsort ||
      config.roleSetups.some((row) => row.role === Role.TimeWolfConsort && row.count > 0)) &&
    !isTimeConsortPreset(config)
  )
    return "time_consort_preset_invalid";
  if (
    (config.wolfSorcerer ||
      config.roleSetups.some((row) => row.role === Role.WolfSorcerer && row.count > 0)) &&
    !isWolfSorcererPreset(config)
  )
    return "wolf_sorcerer_preset_invalid";
  if (
    (config.magician ||
      config.roleSetups.some((row) => row.role === Role.Magician && row.count > 0)) &&
    !isMagicianPreset(config)
  )
    return "magician_preset_invalid";
  if (
    (config.redMoon ||
      config.roleSetups.some((row) => row.role === Role.RedMoonApostle && row.count > 0)) &&
    !isRedMoonPreset(config)
  )
    return "red_moon_preset_invalid";
  if (
    (config.nightmareShadow ||
      config.roleSetups.some((row) => row.role === Role.NightmareShadow && row.count > 0)) &&
    !isNightmarePreset(config)
  )
    return "nightmare_preset_invalid";
  if (
    (config.evilKnight ||
      config.roleSetups.some((row) => row.role === Role.EvilKnight && row.count > 0)) &&
    !isEvilKnightPreset(config)
  )
    return "evil_knight_preset_invalid";
  if (
    (config.pureWhite ||
      config.wolfWitch ||
      config.roleSetups.some(
        (row) => (row.role === Role.PureWhiteGirl || row.role === Role.WolfWitch) && row.count > 0,
      )) &&
    !isPureWhitePreset(config)
  )
    return "pure_white_preset_invalid";
  if (
    config.roleSetups.some((row) => row.role === Role.DemonHunter && row.count > 0) ||
    config.demonHunter
  )
    if (!isDemonHunterPreset(config)) return "demon_hunter_preset_invalid";
  const ownsGhost = config.roleSetups.some((row) => row.role === Role.GhostBride && row.count > 0);
  if (
    ownsGhost ||
    config.ghostBride ||
    config.winConditions?.includes(WinCondition.ThreeFactionsElimination) ||
    config.winCondition === WinCondition.ThreeFactionsElimination
  )
    if (!isGhostBridePreset(config)) return "ghost_bride_preset_invalid";
  if (
    (config.orderPrince ||
      config.roleSetups.some((row) => row.role === Role.OrderPrince && row.count > 0)) &&
    !isOrderPrincePreset(config)
  )
    return "order_prince_preset_invalid";
  return null;
}

/**
 * 负责按原 World 对象绑定唯一不可变板子参数。输入为完整自有数据配置；输出为深只读
 * 执行视图、独立归档 DTO 或明确的数据／修订错误。Node Proxy 检测先于反射；不执行
 * accessor、迭代器或继承字段。只冻结校验后副本，不冻结调用方对象、World 或处理器。
 * 相等完整输入复用原所有者；同一 World 不支持参数替换或重置。绑定不读 World 方法、
 * 时钟或 RNG，也不授予行动权限；安全结构预检保留原板子拒绝优先级，再做完整 schema 校验。
 */
import { types } from "node:util";
import {
  boardConfigSchema,
  type BoardConfig,
  type ReadonlyBoardConfig,
} from "@ai-werewolf-arena/game-contract";
import { boardPresetViolation } from "./board-support";

// 权威按 World 原对象身份保存；工厂实例与私有构造凭据分别防止外部伪造已编译参数。
const owners = new WeakMap<object, BoardParameters>();
const factoryInstances = new WeakSet<object>();
const constructionToken = Symbol("board-parameters-construction");
const dataError = "rule_parameters_not_data";

/** 先验证自有描述符；只有已证明的纯数据才传给 structuredClone，拒绝路径不触发 getter。 */
function assertData(value: unknown, ancestors: Set<object>, depth: number): void {
  if (
    value === undefined ||
    value === null ||
    typeof value === "string" ||
    typeof value === "boolean" ||
    (typeof value === "number" && Number.isFinite(value))
  )
    return;
  if (typeof value !== "object" || types.isProxy(value) || depth > 16 || ancestors.has(value))
    throw new Error(dataError);
  // 数组必须是稠密标准数组；普通对象仅接受标准或 null 原型，symbol／accessor 不进入后续克隆。
  const array = Array.isArray(value),
    prototype = Object.getPrototypeOf(value);
  if (array ? prototype !== Array.prototype : prototype !== Object.prototype && prototype !== null)
    throw new Error(dataError);
  const descriptors = Object.getOwnPropertyDescriptors(value);
  if (Reflect.ownKeys(descriptors).some((key) => typeof key !== "string"))
    throw new Error(dataError);
  if (array) {
    const length = descriptors.length?.value;
    if (
      !Number.isSafeInteger(length) ||
      length < 0 ||
      Object.keys(descriptors).length !== length + 1 ||
      !Array.from({ length }, (_, index) => Object.hasOwn(descriptors, String(index))).every(
        Boolean,
      )
    )
      throw new Error(dataError);
  }
  // 只记录当前递归祖先：拒绝环，允许不同路径共享同一数据对象；finally 保持分支隔离。
  ancestors.add(value);
  try {
    for (const [key, descriptor] of Object.entries(descriptors)) {
      if (array && key === "length") continue;
      if (!Object.hasOwn(descriptor, "value") || !descriptor.enumerable) throw new Error(dataError);
      assertData(descriptor.value, ancestors, depth + 1);
    }
  } finally {
    ancestors.delete(value);
  }
}

/** 递归冻结已复制并解析的数据；不把外部输入引用变成只读。 */
function freezeData(value: unknown): void {
  if (!value || typeof value !== "object") return;
  for (const descriptor of Object.values(Object.getOwnPropertyDescriptors(value))) {
    freezeData(descriptor.value);
  }
  Object.freeze(value);
}

/** 比较完整数据值而非字段插入顺序；两侧均已校验，不读取可替换上下文别名。 */
function equalData(left: unknown, right: unknown): boolean {
  if (left === null || right === null || typeof left !== "object" || typeof right !== "object")
    return Object.is(left, right);
  if (Array.isArray(left) !== Array.isArray(right)) return false;
  const leftKeys = Object.keys(left).sort(),
    rightKeys = Object.keys(right).sort();
  return (
    leftKeys.length === rightKeys.length &&
    leftKeys.every(
      (key, index) =>
        key === rightKeys[index] &&
        equalData(
          Object.getOwnPropertyDescriptor(left, key)!.value,
          Object.getOwnPropertyDescriptor(right, key)!.value,
        ),
    )
  );
}

/** 唯一参数所有者持有深冻结配置；encode 返回可修改的独立归档副本，不修改运行规则。 */
export class BoardParameters {
  readonly #board: BoardConfig;

  private constructor(token: typeof constructionToken, board: BoardConfig) {
    if (token !== constructionToken) throw new Error("rule_parameters_constructor_forbidden");
    freezeData(board);
    this.#board = board;
    Object.freeze(this);
    factoryInstances.add(this);
  }

  static compile(input: unknown): BoardParameters {
    assertData(input, new Set(), 0);
    const copied = structuredClone(input);
    // 这里只预检原板子分派会解引用的两份结构；不代表完整规范化通过，也不是运行时许可。
    if (
      !copied ||
      typeof copied !== "object" ||
      Array.isArray(copied) ||
      !Array.isArray(Object.getOwnPropertyDescriptor(copied, "roleSetups")?.value)
    )
      throw new Error("rule_parameters_invalid");
    const rows: unknown[] = Object.getOwnPropertyDescriptor(copied, "roleSetups")!.value;
    const conditions: unknown = Object.getOwnPropertyDescriptor(copied, "winConditions")?.value;
    if (
      (conditions !== undefined && !Array.isArray(conditions)) ||
      rows.some(
        (row) =>
          !row ||
          typeof row !== "object" ||
          Array.isArray(row) ||
          typeof Object.getOwnPropertyDescriptor(row, "role")?.value !== "string" ||
          typeof Object.getOwnPropertyDescriptor(row, "count")?.value !== "number",
      )
    )
      throw new Error("rule_parameters_invalid");
    // 先保留原板子拒绝的错误优先级；后续严格 schema 成功才允许创建参数所有者。
    const violation = boardPresetViolation(copied as ReadonlyBoardConfig);
    if (violation) throw new Error(violation);
    const parsed = boardConfigSchema.safeParse(copied);
    if (!parsed.success) throw new Error("rule_parameters_invalid");
    return new BoardParameters(constructionToken, parsed.data);
  }

  /** 返回所有者的同一只读引用，供运行期按身份核验。 */
  get board(): ReadonlyBoardConfig {
    return this.#board;
  }

  /** 每次产生独立副本；归档数据不能反向替换 World 已绑定的执行参数。 */
  encode(): BoardConfig {
    return structuredClone(this.#board);
  }
}
Object.freeze(BoardParameters.prototype);
Object.freeze(BoardParameters);

function isFactoryParameters(input: object): input is BoardParameters {
  return factoryInstances.has(input);
}

/** 只发布一次；同值新输入仍先校验／编译再复用旧所有者，异值修订按原错误拒绝。 */
export function bindBoardParameters(
  worldIdentity: object,
  input: ReadonlyBoardConfig | BoardParameters,
): BoardParameters {
  const previous = owners.get(worldIdentity);
  // 唯有已绑定视图的同一引用直接返回；其它候选失败不改变旧绑定，首次编译成功后才写入。
  if (previous && input === previous.board) return previous;
  if (types.isProxy(input)) throw new Error(dataError);
  const candidate = isFactoryParameters(input) ? input : BoardParameters.compile(input);
  if (previous) {
    if (!equalData(previous.board, candidate.board))
      throw new Error("rule_parameters_revision_not_supported");
    return previous;
  }
  owners.set(worldIdentity, candidate);
  return candidate;
}

/** 只查原 World 身份的权威绑定；缺失即失败，不信任可替换上下文，也不临时编译新来源。 */
export function requireBoardParameters(worldIdentity: object): BoardParameters {
  const parameters = owners.get(worldIdentity);
  if (!parameters) throw new Error("rule_parameters_not_bound");
  return parameters;
}

/**
 * 负责 bootstrap 的有限板子拒绝顺序与角色牌组构造。输入为原只读板子、可选固定底牌及窄 Catalog／事件支持查询；输出为原可写牌序或首个原拒绝。工厂及资料字段仍在原重复调用点读取，不复制或冻结来源。不创建 World／组件、消费 RNG、解析外部配置或授予权限；洗牌与装配时点仍由 bootstrap 维护。
 */
import type { ReadonlyBoardConfig } from "@ai-werewolf-arena/game-contract";
import { Camp, Role, WinCondition } from "@ai-werewolf-arena/game-contract";
import { boardPresetViolation } from "./board-support";

/** 只读元数据查询保留原 Catalog／profile 身份；每次调用仍由装配方取得当前目录。 */
export interface SupportedRoleDeckCatalog {
  readonly requireMetadata: (role: Role) => {
    readonly maxCount?: number;
    readonly supportedWinConditions?: readonly WinCondition[];
    readonly supportedBoardRoles?: readonly Role[];
  };
  readonly getCamp: (role: Role) => Camp;
}

export function buildSupportedRoleDeck(
  config: ReadonlyBoardConfig,
  fixedRoles: readonly Role[] | undefined,
  getDefaultRoleCatalog: () => SupportedRoleDeckCatalog,
  supportsWallRoles: (roles: readonly Role[]) => boolean,
): Role[] {
  const presetViolation = boardPresetViolation(config);
  if (presetViolation) throw new Error(presetViolation);
  const deck: Role[] = [];
  for (const setup of config.roleSetups) {
    for (let i = 0; i < setup.count; i++) {
      deck.push(setup.role);
    }
  }

  if (
    config.events &&
    (!supportsWallRoles(deck) || config.events.pack !== "awa_wall_notes_once_v1")
  )
    throw new Error("event_pack_combination_not_supported");
  // 先检查事件组合，再按牌组首次出现顺序检查全部角色上限，随后核支持集合；首个失败不继续后续读取。
  const counts = new Map<Role, number>();
  for (const role of deck) counts.set(role, (counts.get(role) ?? 0) + 1);
  for (const [role, count] of counts) {
    const maximum = getDefaultRoleCatalog().requireMetadata(role).maxCount;
    if (maximum !== undefined && count > maximum)
      throw new Error(`role_count_exceeds_limit: ${role}`);
  }
  for (const role of counts.keys()) {
    const profile = getDefaultRoleCatalog().requireMetadata(role);
    const conditions = config.winConditions?.length
      ? config.winConditions
      : [config.winCondition ?? WinCondition.SlaughterCity];
    if (
      profile.supportedWinConditions &&
      (new Set(conditions).size !== conditions.length ||
        conditions.some((condition) => !profile.supportedWinConditions!.includes(condition)))
    )
      throw new Error(`role_win_condition_not_supported: ${role}`);
    const supported = profile.supportedBoardRoles;
    if (supported && [...counts.keys()].some((candidate) => !supported.includes(candidate)))
      throw new Error(`role_combination_not_supported: ${role}`);
  }

  if (deck.length !== config.boardSize) {
    throw new Error(`Role setup mismatch: boardSize=${config.boardSize}, roles=${deck.length}`);
  }

  if (
    config.thief &&
    (!counts.has(Role.Thief) || config.thief.policy !== "lui_meme_thief_two_extra_villagers_v1")
  )
    throw new Error("thief_policy_invalid");
  if (
    config.lonelyGirl &&
    (!counts.has(Role.LonelyGirl) || config.lonelyGirl.policy !== "awa_netease_lonely_girl_v1")
  )
    throw new Error("lonely_girl_policy_invalid");
  if (
    counts.has(Role.LonelyGirl) &&
    (config.boardSize < 6 ||
      !counts.has(Role.Wolf) ||
      ![...counts.keys()].some(
        (role) => role !== Role.LonelyGirl && getDefaultRoleCatalog().getCamp(role) === Camp.Good,
      ))
  )
    throw new Error("lonely_girl_finite_composition_required");
  if (
    config.wildChild &&
    (!counts.has(Role.WildChild) || config.wildChild.policy !== "awa_lui_meme_wild_child_v1")
  )
    throw new Error("wild_child_policy_invalid");
  if (
    counts.has(Role.WildChild) &&
    ((counts.get(Role.Wolf) ?? 0) < 1 ||
      [...counts]
        .filter(
          ([role]) =>
            role !== Role.WildChild && getDefaultRoleCatalog().getCamp(role) === Camp.Good,
        )
        .reduce((n, [, count]) => n + count, 0) < 1)
  )
    throw new Error("wild_child_finite_composition_required");
  if (
    config.shapeshifter &&
    (!counts.has(Role.Shapeshifter) ||
      config.shapeshifter.policy !== "awa_netease_shapeshifter_two_extra_villagers_v1")
  )
    throw new Error("shapeshifter_policy_invalid");
  if (counts.has(Role.Shapeshifter)) {
    if (
      config.boardSize < 6 ||
      (counts.get(Role.Wolf) ?? 0) < 2 ||
      [...counts]
        .filter(
          ([role]) =>
            role !== Role.Shapeshifter && getDefaultRoleCatalog().getCamp(role) === Camp.Good,
        )
        .reduce((n, [, count]) => n + count, 0) < 1
    )
      throw new Error("shapeshifter_finite_composition_required");
    deck.push(Role.Villager, Role.Villager);
  }
  if (counts.has(Role.Thief)) {
    if (
      (counts.get(Role.Wolf) ?? 0) < 2 ||
      [...counts]
        .filter(
          ([role]) => role !== Role.Thief && getDefaultRoleCatalog().getCamp(role) === Camp.Good,
        )
        .reduce((n, [, count]) => n + count, 0) < 2
    )
      throw new Error("thief_finite_composition_required");
    deck.push(Role.Villager, Role.Villager);
  }
  // 盗贼／千面人合法性与额外底牌已准备完毕，才比对固定底牌多重集；成功返回新数组且不洗牌。
  if (fixedRoles) {
    if (
      fixedRoles.length !== deck.length ||
      [...fixedRoles].sort().join(",") !== [...deck].sort().join(",")
    )
      throw new Error("fixed_role_deck_mismatch");
    return [...fixedRoles];
  }
  return deck;
}

/**
 * 负责校验和规范化公开板子格式。输入为纯公开 JSON 与已登记角色声明；输出为原 BoardConfig、诊断和反向序列化配置。解析拥有字段／默认值规范化，规则集拥有有限支持裁决；不读取认证、执行对局或授予行动租约。
 */
import { boardPresetViolation } from "../../rulesets";
/** 唯一公开板子格式；未知字段和未注册角色保持原拒绝。 */
import { supportsWallRoles } from "../../game/mechanisms/events/wall_notes/authority";
import { z } from "zod";
import { RULESET } from "@ai-werewolf-arena/game-catalog";
import { ROLE_IDS, isRoleId } from "@ai-werewolf-arena/game-contract";
import { ActionWindow, Camp, Role, WinCondition, type BoardConfig } from "../../core/domain/model";
import { getDefaultRoleCatalog } from "../../game/mechanisms/roles/role-catalog-assembly";
import {
  EVENT_PACK_IDS,
  DEATH_REVEAL_POLICIES,
  LAST_WORDS_POLICIES,
  SHERIFF_BADGE_POLICIES,
  SHERIFF_ELECTION_POLICIES,
  EXILE_VOTE_POLICIES,
} from "../../core/domain/board";
import { boardConfigSchema } from "../../core/domain/board_schema";

export const CONFIG_ID_PATTERN = /^[a-z][a-z0-9_-]*$/;
export const MAX_BOARD_PLAYERS = 128;
export const boardIdSchema = z.string().regex(CONFIG_ID_PATTERN);
const safePositive = z.number().int().positive().max(Number.MAX_SAFE_INTEGER);
const hooks = z.strictObject({
  onDaybreak: z.boolean(),
  onPreElection: z.boolean(),
  onPreVote: z.boolean(),
  onPerSpeechGap: z.boolean(),
});
const schema = z.strictObject({
  version: z.literal(2),
  id: boardIdSchema,
  ruleset: z.strictObject({ id: z.literal(RULESET.id), version: z.literal(RULESET.version) }),
  board: z.strictObject({
    size: safePositive.max(MAX_BOARD_PLAYERS),
    roleSetups: z
      .array(
        z.strictObject({
          role: z.enum(ROLE_IDS as [string, ...string[]]),
          count: safePositive.max(MAX_BOARD_PLAYERS),
        }),
      )
      .min(1),
  }),
  rules: z.strictObject({ winConditions: z.array(z.enum(WinCondition)).min(1), hooks }),
  mechanisms: z.strictObject({
    eventPack: z.enum(EVENT_PACK_IDS).optional(),
    disclosure: z
      .strictObject({ deathRevealPolicy: z.enum(DEATH_REVEAL_POLICIES).default("awa_hidden_v1") })
      .default({ deathRevealPolicy: "awa_hidden_v1" }),
    lastWords: z
      .strictObject({ policy: z.enum(LAST_WORDS_POLICIES).default("awa_initial_wave_v1") })
      .default({ policy: "awa_initial_wave_v1" }),
    sheriff: z.strictObject({
      enabled: z.boolean(),
      electionPolicy: z.enum(SHERIFF_ELECTION_POLICIES).default("awa_final_candidates_v1"),
      badgePolicy: z.enum(SHERIFF_BADGE_POLICIES).default("awa_next_seat_v1"),
      initialSeat: safePositive.optional(),
      voteWeight: z.number().finite().positive().default(1.5),
      tieBreaker: z.enum(["min_id", "min_seat", "no_elimination"]).default("min_seat"),
    }),
    voting: z
      .strictObject({ exilePolicy: z.enum(EXILE_VOTE_POLICIES).default("awa_direct_v1") })
      .default({ exilePolicy: "awa_direct_v1" }),
    selfDestruct: z.strictObject({ enabledWindows: z.array(z.enum(ActionWindow)) }),
    tieBreaker: z.strictObject({
      exileVote: z.enum(["min_id", "no_elimination"]),
      wolfKillVote: z.enum(["min_id", "no_kill"]),
    }),
  }),
  roles: z.record(z.string(), z.unknown()).default({}),
});

export type BoardDefinition = z.infer<typeof schema>;
export interface ResolvedBoardDefinition {
  definition: BoardDefinition;
  config: BoardConfig;
  sourceFile?: string;
  fieldSources: Readonly<Record<string, "explicit" | "default">>;
}

export class BoardConfigurationError extends Error {
  constructor(
    readonly code: string,
    readonly fieldPath: string,
  ) {
    super(`${code}: ${fieldPath}`);
  }
}
function fail(code: string, path: string): never {
  throw new BoardConfigurationError(code, path);
}

export function parseBoardDefinition(raw: unknown, expectedId?: string): ResolvedBoardDefinition {
  const result = schema.safeParse(raw);
  if (!result.success) {
    const issue = result.error.issues[0];
    const key = issue.code === "unrecognized_keys" ? issue.keys[0] : undefined;
    fail(
      "board_config_invalid_field",
      [...issue.path, ...(key ? [key] : [])].join(".") || "document",
    );
  }
  const definition = result.data;
  if (expectedId !== undefined && definition.id !== expectedId)
    fail("board_config_id_mismatch", "id");
  const catalog = getDefaultRoleCatalog();
  const seen = new Set<string>();
  let total = 0;
  for (const [index, entry] of definition.board.roleSetups.entries()) {
    if (!isRoleId(entry.role) || !catalog.metadata(entry.role as Role))
      fail("board_config_role_not_implemented", `board.roleSetups.${index}.role`);
    if (seen.has(entry.role)) fail("board_config_duplicate_role", `board.roleSetups.${index}.role`);
    const maximum = catalog.requireMetadata(entry.role as Role).maxCount;
    if (maximum !== undefined && entry.count > maximum)
      fail("board_config_invalid_field", `board.roleSetups.${index}.count`);
    seen.add(entry.role);
    total += entry.count;
  }
  if (total !== definition.board.size) fail("board_config_role_count_mismatch", "board.roleSetups");
  if (
    definition.board.roleSetups.some((row) => row.role === "shapeshifter") &&
    (definition.board.size < 6 ||
      definition.board.roleSetups
        .filter((row) => row.role === "wolf")
        .reduce((n, row) => n + row.count, 0) < 2 ||
      !definition.board.roleSetups.some(
        (row) => row.role !== "shapeshifter" && catalog.getCamp(row.role as Role) === Camp.Good,
      ))
  )
    fail("board_config_role_combination_not_supported", "board.roleSetups");
  if (definition.board.roleSetups.some((row) => row.role === "thief")) {
    const wolves = definition.board.roleSetups
        .filter((row) => row.role === "wolf")
        .reduce((n, row) => n + row.count, 0),
      good = definition.board.roleSetups
        .filter((row) => row.role !== "thief" && catalog.getCamp(row.role as Role) === Camp.Good)
        .reduce((n, row) => n + row.count, 0);
    if (wolves < 2 || good < 2)
      fail("board_config_role_combination_not_supported", "board.roleSetups");
  }
  if (
    definition.board.roleSetups.some((row) => row.role === "wild_child") &&
    !definition.board.roleSetups.some(
      (row) => row.role !== "wild_child" && catalog.getCamp(row.role as Role) === Camp.Good,
    )
  )
    fail("board_config_role_combination_not_supported", "board.roleSetups");
  if (
    definition.board.roleSetups.some((row) => row.role === "lonely_girl") &&
    (definition.board.size < 6 ||
      !definition.board.roleSetups.some((row) => row.role === "wolf") ||
      !definition.board.roleSetups.some(
        (row) => row.role !== "lonely_girl" && catalog.getCamp(row.role as Role) === Camp.Good,
      ))
  )
    fail("board_config_role_combination_not_supported", "board.roleSetups");
  const profiles = definition.board.roleSetups.map((entry) =>
    catalog.requireMetadata(entry.role as Role),
  );
  for (const profile of profiles) {
    if (
      profile.supportedBoardRoles &&
      definition.board.roleSetups.some(
        (entry) => !profile.supportedBoardRoles!.includes(entry.role as Role),
      )
    ) {
      fail("board_config_role_combination_not_supported", "board.roleSetups");
    }
  }
  if (
    !profiles.some((item) => item.camp === Camp.Wolf) ||
    !profiles.some((item) => item.camp === Camp.Good)
  ) {
    fail("board_config_requires_good_and_wolf", "board.roleSetups");
  }
  for (const profile of profiles)
    if (
      profile.supportedWinConditions &&
      definition.rules.winConditions.some(
        (condition) => !profile.supportedWinConditions!.includes(condition),
      )
    )
      fail("board_config_role_win_condition_not_supported", "rules.winConditions");
  if (new Set(definition.rules.winConditions).size !== definition.rules.winConditions.length)
    fail("board_config_duplicate_win_condition", "rules.winConditions");
  if (
    definition.mechanisms.eventPack &&
    !supportsWallRoles(definition.board.roleSetups.map((e) => e.role as Role))
  )
    fail("board_config_role_combination_not_supported", "mechanisms.eventPack");
  const sheriff = definition.mechanisms.sheriff;
  if (sheriff.initialSeat && sheriff.initialSeat > total)
    fail("board_config_seat_out_of_range", "mechanisms.sheriff.initialSeat");
  if (
    !sheriff.enabled &&
    (sheriff.initialSeat ||
      sheriff.voteWeight !== 1.5 ||
      sheriff.tieBreaker !== "min_seat" ||
      sheriff.electionPolicy !== "awa_final_candidates_v1" ||
      sheriff.badgePolicy !== "awa_next_seat_v1")
  ) {
    fail("board_config_disabled_mechanism_parameters", "mechanisms.sheriff");
  }
  const windows = definition.mechanisms.selfDestruct.enabledWindows;
  if (new Set(windows).size !== windows.length)
    fail("board_config_duplicate_window", "mechanisms.selfDestruct.enabledWindows");
  const windowHooks = {
    [ActionWindow.OnPreVote]: "onPreVote",
    [ActionWindow.OnDaybreak]: "onDaybreak",
    [ActionWindow.OnPreElection]: "onPreElection",
    [ActionWindow.OnPerSpeechGap]: "onPerSpeechGap",
  } as const;
  for (const window of windows)
    if (!definition.rules.hooks[windowHooks[window]])
      fail("board_config_window_hook_disabled", `rules.hooks.${windowHooks[window]}`);
  if (definition.rules.winConditions.includes(WinCondition.SlaughterSide)) {
    if (
      !profiles.some((item) => item.goodSide === "god") ||
      !profiles.some((item) => item.goodSide === "villager")
    ) {
      fail("board_config_slaughter_side_requires_both_sides", "rules.winConditions");
    }
  }
  let config: BoardConfig = {
    boardSize: total,
    roleSetups: definition.board.roleSetups.map((entry) => ({
      role: entry.role as Role,
      count: entry.count,
    })),
    winConditions: [...definition.rules.winConditions],
    hooks: { ...definition.rules.hooks },
    enableSheriff: sheriff.enabled,
    ...(sheriff.initialSeat ? { initialSheriffSeat: sheriff.initialSeat } : {}),
    ...(sheriff.enabled
      ? {
          sheriff: {
            voteWeight: sheriff.voteWeight,
            electionPolicy: sheriff.electionPolicy,
            badgePolicy: sheriff.badgePolicy,
          },
        }
      : {}),
    selfDestruct: { enabledWindows: [...windows] },
    ...(definition.mechanisms.eventPack
      ? { events: { pack: definition.mechanisms.eventPack } }
      : {}),
    voting: { ...definition.mechanisms.voting },
    disclosure: { ...definition.mechanisms.disclosure },
    lastWords: { ...definition.mechanisms.lastWords },
    tieBreaker: {
      ...definition.mechanisms.tieBreaker,
      ...(sheriff.enabled ? { sheriffVote: sheriff.tieBreaker } : {}),
    },
  };
  for (const [id, value] of Object.entries(definition.roles)) {
    if (!seen.has(id)) fail("board_config_role_parameters_without_role", `roles.${id}`);
    const contribution = catalog.requireRuntime(id as Role).configuration;
    if (!contribution) fail("board_config_role_parameters_not_supported", `roles.${id}`);
    const parsed = contribution.schema.safeParse(value);
    if (!parsed.success) {
      const issue = parsed.error.issues[0];
      const unknown = issue.code === "unrecognized_keys" ? issue.keys[0] : undefined;
      fail(
        "board_config_invalid_field",
        ["roles", id, ...issue.path, ...(unknown ? [unknown] : [])].join("."),
      );
    }
    definition.roles[id] = parsed.data;
    config = contribution.apply(config, parsed.data);
  }
  for (const id of seen) {
    const contribution = catalog.requireRuntime(id as Role).configuration;
    if (contribution && !(id in definition.roles)) {
      const defaults = contribution.schema.parse(contribution.defaults);
      definition.roles[id] = defaults;
      config = contribution.apply(config, defaults);
    }
  }
  const presetViolation = boardPresetViolation(config);
  if (presetViolation) fail(`board_config_${presetViolation}`, "board");
  const fieldSources: Record<string, "explicit" | "default"> = {};
  const recordSources = (value: unknown, original: unknown, prefix: string) => {
    if (value && typeof value === "object" && !Array.isArray(value)) {
      for (const [key, entry] of Object.entries(value)) {
        const prior =
          original && typeof original === "object"
            ? (original as Record<string, unknown>)[key]
            : undefined;
        recordSources(entry, prior, prefix ? `${prefix}.${key}` : key);
      }
    } else fieldSources[prefix] = original === undefined ? "default" : "explicit";
  };
  recordSources(definition, raw, "");
  return { definition, config, fieldSources };
}

/** 公开板子只含实际角色的参数；Tape 仍保留完整内部板子。 */
export function boardDefinitionFromConfig(id: string, config: BoardConfig): BoardDefinition {
  const valid = boardConfigSchema.safeParse(config);
  if (!valid.success) {
    const issue = valid.error.issues[0];
    const key = issue.code === "unrecognized_keys" ? issue.keys[0] : undefined;
    fail("board_config_invalid_field", ["config", ...issue.path, ...(key ? [key] : [])].join("."));
  }
  const catalog = getDefaultRoleCatalog();
  const roles: Record<string, unknown> = {};
  for (const entry of config.roleSetups.filter((entry) => entry.count > 0)) {
    const contribution = catalog.requireRuntime(entry.role).configuration;
    if (contribution) roles[entry.role] = contribution.serialize(config);
  }
  const conditions = config.winConditions?.length
    ? config.winConditions
    : [config.winCondition ?? WinCondition.SlaughterCity];
  return parseBoardDefinition({
    version: 2,
    id,
    ruleset: RULESET,
    board: {
      size: config.boardSize,
      roleSetups: config.roleSetups.filter((entry) => entry.count > 0),
    },
    rules: { winConditions: conditions, hooks: config.hooks },
    mechanisms: {
      ...(config.events ? { eventPack: config.events.pack } : {}),
      disclosure: { deathRevealPolicy: config.disclosure?.deathRevealPolicy ?? "awa_hidden_v1" },
      lastWords: { policy: config.lastWords?.policy ?? "awa_initial_wave_v1" },
      sheriff: {
        enabled: config.enableSheriff,
        ...(config.enableSheriff
          ? {
              ...(config.initialSheriffSeat !== undefined
                ? { initialSeat: config.initialSheriffSeat }
                : {}),
              voteWeight: config.sheriff?.voteWeight ?? 1.5,
              electionPolicy: config.sheriff?.electionPolicy ?? "awa_final_candidates_v1",
              badgePolicy: config.sheriff?.badgePolicy ?? "awa_next_seat_v1",
              tieBreaker: config.tieBreaker?.sheriffVote ?? "min_seat",
            }
          : {}),
      },
      voting: { exilePolicy: config.voting?.exilePolicy ?? "awa_direct_v1" },
      selfDestruct: {
        enabledWindows: (config.selfDestruct?.enabledWindows ?? [ActionWindow.OnPreVote]).filter(
          (window) =>
            ({
              [ActionWindow.OnPreVote]: config.hooks.onPreVote,
              [ActionWindow.OnDaybreak]: config.hooks.onDaybreak,
              [ActionWindow.OnPreElection]: config.hooks.onPreElection,
              [ActionWindow.OnPerSpeechGap]: config.hooks.onPerSpeechGap,
            })[window],
        ),
      },
      tieBreaker: {
        exileVote: config.tieBreaker?.exileVote ?? "min_id",
        wolfKillVote: config.tieBreaker?.wolfKillVote ?? "min_id",
      },
    },
    roles,
  }).definition;
}

